let timer = null;
let n = 0;
function tick() { n++; console.log("Tık", n); if (n === 3) stop(); }
function start() {
  if (timer !== null) return; // zaten çalışıyor
  timer = setInterval(tick, 100);
}
function stop() { clearInterval(timer); timer = null; }
start();
